#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    printf("How many students? ");
    if (scanf("%d", &n) != 1 || n <= 0) {
        printf("Please enter a positive number.\n");
        return 1;
    }

    int *marks = malloc(n * sizeof(int));
    if (marks == NULL) {
        printf("Could not get memory.\n");
        return 1;
    }

    for (int i = 0; i < n; i++) {
        marks[i] = 60 + i * 10;
    }

    for (int i = 0; i < n; i++) {
        printf("Student %d: %d\n", i + 1, marks[i]);
    }

    free(marks);
    marks = NULL;
    return 0;
}

