printf("How many marks? ");
if (scanf("%d", &n) != 1 || n <= 0) return 1;

int *marks = malloc(n * sizeof(int));
if (marks == NULL) return 1;

int total = 0;
for (int i = 0; i < n; i++) {
    printf("Mark %d: ", i + 1);
    scanf("%d", &marks[i]);
    total += marks[i];
}
printf("Average: %.2f\n", (double)total / n);   /* 70 80 95 gives 81.67 */

free(marks);

